/** Tin chat là sticker → id, không thì null. */
export const stickerOf = (text) => {
  const m = /^:stk:([a-z]+):$/.exec(text || "")
  return m && STICKERS[m[1]] ? m[1] : null
}
export const stickerText = (id) => ":stk:" + id + ":"

